import{defineComponent,onMounted,onBeforeUnmount,watch}from"vue";import{useAddressStore}from"../vue/stores/AddressStore";export default defineComponent({name:"AddressHydrator",props:{rootEl:{type:HTMLElement,required:true},config:{type:Object,required:true}},setup(props){const store=useAddressStore();const cleanups=[];const registerCleanup=fn=>cleanups.push(fn);const setElDisplay=(el,display)=>{if(!el){return}el.style.display=display};const syncToggleUi=({toggleEl,textEl,iconEl},cfg)=>{if(!cfg){return}const style=cfg.style||"both";setElDisplay(toggleEl,style==="hidden"?"none":"");if(textEl){if(style==="icon"){setElDisplay(textEl,"none")}else{setElDisplay(textEl,"");textEl.textContent=cfg.text||""}}if(iconEl){if(style==="text"||!cfg.icon){setElDisplay(iconEl,"none");iconEl.removeAttribute("src")}else{setElDisplay(iconEl,"");iconEl.setAttribute("src",cfg.icon)}}};store.initFromDom(props.rootEl,props.config);onMounted(()=>{const root=props.rootEl;store.connectDom(root);store.connectAutocomplete(root);store.connectMap(root);const toggleEl=root.querySelector("[data-gm-toggle]");if(!toggleEl){return}const toggleUi={toggleEl:toggleEl,textEl:toggleEl.querySelector("[data-gm-toggle-text]"),iconEl:toggleEl.querySelector("[data-gm-toggle-icon]")};const onClick=event=>{event.preventDefault();store.changeVisibility()};toggleEl.addEventListener("click",onClick);registerCleanup(()=>toggleEl.removeEventListener("click",onClick));const stopToggleWatch=watch(()=>store.configToggle,cfg=>syncToggleUi(toggleUi,cfg),{immediate:true,deep:true});registerCleanup(stopToggleWatch);const stopMarginWatch=watch(()=>store.marginTop,offset=>{const px=typeof offset==="number"?offset:0;toggleEl.style.marginTop=`${px}px`},{immediate:true});registerCleanup(stopMarginWatch);const toggleContainer=root.querySelector(".map-toggle-container");if(toggleContainer){toggleContainer.classList.add("is-hydrated")}});onBeforeUnmount(()=>{cleanups.forEach(fn=>{try{fn()}catch(e){}});store.disconnectAutocomplete();store.disconnectDom();store.disconnectMap()});return{addressStore:store}}});